import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert an integer to a base-36 string (uppercase)."""
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    """Convert a base-36 string (uppercase) to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch)
    return n


def next_id(current: str) -> str:
    """Increment a 4-character base-36 order id suffix."""
    suffix = current.split("-")[-1]
    num = from_base36(suffix)
    next_num = to_base36(num + 1).zfill(4).upper()
    return f"ORD-{next_num}"


