"""Print the next order id by reading ids.txt (one id per line, most recent last).

Ids have the form ORD- followed by four base36 characters (0-9, A-Z).
"""

import sys
from pathlib import Path


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base36 string."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return chars[0] * width
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result)).rjust(width, chars[0])


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    return int(s, 36)


def main() -> None:
    ids_path = Path("ids.txt")
    if not ids_path.exists():
        print("error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    lines = ids_path.read_text(encoding="utf-8").strip().splitlines()
    if not lines:
        print("error: ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1].strip()
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"error: unexpected id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    try:
        num = base36_decode(suffix)
    except ValueError:
        print(f"error: cannot parse suffix {suffix!r}", file=sys.stderr)
        sys.exit(1)

    next_num = num + 1
    if next_num >= 36 ** 4:
        print("error: id space exhausted", file=sys.stderr)
        sys.exit(1)

    next_id = "ORD-" + base36_encode(next_num)
    print(next_id)


if __name__ == "__main__":
    main()

