"""Print report file names under reports/ in report order, one per line."""

import os
import re

REPORTS_DIR = "reports"


def report_sort_key(filename: str) -> int:
    """Extract the numeric report number from a filename like report-<n>.txt."""
    match = re.search(r"report-(\d+)\.txt$", filename)
    if match is None:
        return float("inf")
    return int(match.group(1))


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        print(f"error: '{REPORTS_DIR}' directory not found", file=__import__("sys").stderr)
        raise SystemExit(1)

    # Keep only report-<n>.txt files and sort them numerically
    report_files = sorted(
        (e for e in entries if re.match(r"report-\d+\.txt$", e)),
        key=report_sort_key,
    )

    for f in report_files:
        print(f)


if __name__ == "__main__":
    main()

