"""Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds.

Reads app.log (one entry per line, each starting with YYYY-MM-DD HH:MM:SS).
Moves entries strictly older than 7 days before AS_OF to archive.log
(appending, preserving order). Rewrites app.log with remaining entries.
"""

import datetime
import sys
import time


def parse_timestamp(line: str) -> datetime.datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' prefix from line; return UTC datetime or None."""
    try:
        return datetime.datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=datetime.timezone.utc
        )
    except (ValueError, IndexError):
        return None


def line_timestamp_secs(line: str) -> float | None:
    """Return Unix timestamp of the line prefix, or None."""
    dt = parse_timestamp(line)
    return dt.timestamp() if dt else None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer, got {sys.argv[1]!r}", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 60 * 60  # 7 days before AS_OF

    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    old_entries: list[str] = []
    kept_entries: list[str] = []

    for line in lines:
        ts = line_timestamp_secs(line)
        if ts is not None and ts < cutoff:
            old_entries.append(line)
        else:
            kept_entries.append(line)

    # Append old entries to archive.log
    if old_entries:
        with open("archive.log", "a") as f:
            f.writelines(old_entries)

    # Rewrite app.log with kept entries
    with open("app.log", "w") as f:
        f.writelines(kept_entries)


if __name__ == "__main__":
    main()

